def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0, c1+1))
            perimeter &= all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0, r1+1))
            if perimeter:
                frames.append((color, r0, r1, c0, c1))

    frame_colors = {f[0] for f in frames}
    marker_counts = {}
    for row in grid:
        for color in row:
            if color and color not in frame_colors:
                marker_counts[color] = marker_counts.get(color, 0) + 1

    targets = []
    for _, r0, r1, c0, c1 in frames:
        ih, iw = r1-r0-1, c1-c0-1
        targets.append((ih*iw + 1)//2)

    markers = list(marker_counts)
    best = None
    def assign(i, used, total, choices):
        nonlocal best
        if i == len(frames):
            if best is None or total < best[0]:
                best = (total, choices[:])
            return
        for color in markers:
            if color not in used:
                choices.append(color)
                assign(i+1, used | {color}, total + abs(marker_counts[color] - targets[i]), choices)
                choices.pop()

    if len(markers) >= len(frames):
        assign(0, set(), 0, [])

    out = [[0] * w for _ in range(h)]
    for i, (color, r0, r1, c0, c1) in enumerate(frames):
        for x in range(c0, c1+1):
            out[r0][x] = color
            out[r1][x] = color
        for y in range(r0, r1+1):
            out[y][c0] = color
            out[y][c1] = color
        if best:
            fill = best[1][i]
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if (y-r0-1 + x-c0-1) % 2 == 0:
                        out[y][x] = fill
    return out
